  @Test
  void core_cancel() throws Exception {
    // during the request: interrupt the calling thread
    server.enqueue(
        ex -> {
          Thread.sleep(3000);
          MockServer.send(ex, 200, "{}");
        });
    try (HttpTransport t = transport(config())) {
      AtomicReference<Throwable> err = new AtomicReference<>();
      AtomicReference<Boolean> interrupted = new AtomicReference<>();
      Thread th =
          new Thread(
              () -> {
                try {
                  t.send(TransportRequest.get("/slow").build());
                } catch (Throwable e) {
                  err.set(e);
                  interrupted.set(Thread.currentThread().isInterrupted());
                }
              });
      th.start();
      Thread.sleep(200);
      th.interrupt();
      th.join(5000);
      assertThat(err.get()).isInstanceOf(CancelledException.class);
      assertThat(interrupted.get()).isTrue();
    }
    // during backoff: the pending retry never happens
    MockServer s2 = MockServer.start();
    s2.fallback(ex -> MockServer.send(ex, 503, "{}"));
    RetryPolicy slow =
        RetryPolicy.builder().initialBackoff(Duration.ofSeconds(5)).random(fixed(0.99)).build();
    try (HttpTransport t =
        new HttpTransport(TransportConfig.builder(s2.url()).retry(slow).build())) {
      CompletableFuture<TransportResponse> f = t.sendAsync(TransportRequest.get("/x").build());
      Thread.sleep(300);
      assertThat(f.cancel(true)).isTrue();
      assertThatThrownBy(f::join).isInstanceOf(CancellationException.class);
      Thread.sleep(200);
      assertThat(s2.requests()).hasSize(1);
      // sync variant: interrupt during backoff
      AtomicReference<Throwable> err = new AtomicReference<>();
      Thread th =
          new Thread(
              () -> {
                try {
                  t.send(TransportRequest.get("/y").build());
                } catch (Throwable e) {
                  err.set(e);
                }
              });
      th.start();
      Thread.sleep(300);
      th.interrupt();
      th.join(5000);
      assertThat(err.get()).isInstanceOf(CancelledException.class);
      assertThat(s2.requests()).hasSize(2);
    } finally {
      s2.close();
    }
  }

