  @Test
  void core_redaction_error_text() {
    String token = "tok-SUPERSECRET-123";
    server.enqueue(
        ex -> {
          String auth = ex.getRequestHeaders().getFirst("Authorization");
          MockServer.send(
              ex, 401, "{\"message\":\"bad credentials " + auth + " and " + token + "\"}");
        });
    List<Hooks.RequestInfo> reqs = new CopyOnWriteArrayList<>();
    List<Hooks.ErrorInfo> errs = new CopyOnWriteArrayList<>();
    List<String> logs = new CopyOnWriteArrayList<>();
    Hooks hooks =
        new Hooks() {
          @Override
          public void onRequest(RequestInfo info) {
            reqs.add(info);
          }

          @Override
          public void onError(ErrorInfo info) {
            errs.add(info);
          }
        };
    Logger logger =
        new Logger() {
          @Override
          public void debug(String message, Map<String, Object> fields) {
            logs.add(message + fields);
          }
        };
    try (HttpTransport t =
        transport(config().hooks(hooks).logger(logger).knownSecrets(() -> List.of(token)))) {
      assertThatThrownBy(
              () ->
                  t.send(
                      TransportRequest.get("/x?token=" + token)
                          .header("Authorization", "Bearer " + token)
                          .operation("ping")
                          .build()))
          .isInstanceOfSatisfying(
              AuthenticationException.class,
              e -> {
                assertThat(e.getMessage()).doesNotContain(token).contains("[REDACTED]");
                assertThat(e.getMessage()).startsWith("ping: unauthorized: bad credentials");
              });
      assertThat(reqs.get(0).headers().get("Authorization")).containsExactly("[REDACTED]");
      assertThat(reqs.get(0).url()).doesNotContain(token);
      assertThat(errs.get(0).error().getMessage()).doesNotContain(token);
      assertThat(errs.get(0).url()).doesNotContain(token);
      assertThat(String.join("", logs)).doesNotContain(token);
    }
  }

  @Test
  void networkErrorCauseIsRedacted() throws Exception {
    int port;
    try (ServerSocket s = new ServerSocket(0)) {
      port = s.getLocalPort();
    }
    List<String> logs = new CopyOnWriteArrayList<>();
    Logger logger =
        new Logger() {
          @Override
          public void debug(String message, Map<String, Object> fields) {
            logs.add(message + fields);
          }
        };
    try (HttpTransport t =
        new HttpTransport(
            TransportConfig.builder("http://127.0.0.1:" + port)
                .logger(logger)
                .retry(
                    RetryPolicy.builder()
                        .maxRetries(1)
                        .initialBackoff(Duration.ofMillis(1))
                        .build())
                .build())) {
      // POST to a closed port: connect failure happens before the send, so it is retried
      assertThatThrownBy(() -> t.send(TransportRequest.post("/x").build()))
          .isInstanceOfSatisfying(
              UnavailableException.class,
              e -> {
                assertThat(e.getMessage()).contains("connection failed");
                assertThat(e.httpStatus()).isEmpty();
              });
      assertThat(logs).hasSize(1);
    }
  }

