  @Test
  void core_hooks() {
    server.enqueue(503, "{}").enqueue(200, "{}", "x-request-id", "r-9");
    List<String> events = new CopyOnWriteArrayList<>();
    Hooks hooks =
        new Hooks() {
          @Override
          public void onRequest(RequestInfo info) {
            events.add("req:" + info.attempt() + ":" + info.method() + ":" + info.url());
            throw new IllegalStateException("hook failure is ignored");
          }

          @Override
          public void onResponse(ResponseInfo info) {
            events.add(
                "resp:"
                    + info.attempt()
                    + ":"
                    + info.status()
                    + ":"
                    + info.requestId().orElse("-"));
            assertThat(info.durationMs()).isNotNegative();
            throw new IllegalStateException("ignored");
          }

          @Override
          public void onError(ErrorInfo info) {
            events.add(
                "err:" + info.attempt() + ":" + info.willRetry() + ":" + info.error().code());
            throw new IllegalStateException("ignored");
          }
        };
    Logger throwing =
        new Logger() {
          @Override
          public void debug(String message, Map<String, Object> fields) {
            throw new IllegalStateException("logger failure is ignored");
          }
        };
    try (HttpTransport t = transport(config().hooks(hooks).logger(throwing))) {
      t.send(TransportRequest.get("/x?api_key=k1&plain=v").build());
    }
    assertThat(events)
        .containsExactly(
            "req:1:GET:" + server.url() + "/x?api_key=[REDACTED]&plain=v",
            "resp:1:503:-",
            "err:1:true:UNAVAILABLE",
            "req:2:GET:" + server.url() + "/x?api_key=[REDACTED]&plain=v",
            "resp:2:200:r-9");
  }

