  @Test
  void resolveJoinsPaths() {
    try (HttpTransport t = new HttpTransport(TransportConfig.builder("http://h:1/api//").build())) {
      assertThat(t.resolve("v1", Map.of())).isEqualTo("http://h:1/api/v1");
      assertThat(t.resolve("/v1", Map.of())).isEqualTo("http://h:1/api/v1");
      assertThat(t.resolve("", Map.of())).isEqualTo("http://h:1/api");
      assertThat(t.resolve("https://o/x", Map.of("a", List.of("1")))).isEqualTo("https://o/x?a=1");
    }
  }

  @Test
  void proxyIsUsedWithCredentials() throws Exception {
    try (MockServer proxy = MockServer.start()) {
      proxy
          .enqueue(407, "", "Proxy-Authenticate", "Basic realm=\"p\"")
          .enqueue(200, "{\"via\":\"proxy\"}");
      try (HttpTransport t =
          new HttpTransport(
              TransportConfig.builder("http://upstream.invalid:9")
                  .proxy("http://user%40x:p%3Ass@" + proxy.url().substring("http://".length()))
                  .build())) {
        TransportResponse r = t.send(TransportRequest.get("/x").build());
        assertThat(r.jsonNode().get("via").asText()).isEqualTo("proxy");
      }
      List<MockServer.Recorded> reqs = proxy.requests();
      assertThat(reqs.get(0).uri()).isEqualTo("http://upstream.invalid:9/x");
      assertThat(reqs.get(1).header("Proxy-Authorization"))
          .isEqualTo(
              "Basic "
                  + java.util.Base64.getEncoder()
                      .encodeToString(
                          "user@x:p:ss".getBytes(java.nio.charset.StandardCharsets.UTF_8)));
    }
  }

  @Test
  void proxyWithoutPasswordAndDefaultPorts() throws Exception {
    try (MockServer proxy = MockServer.start()) {
      proxy.enqueue(200, "{}");
      try (HttpTransport t =
          new HttpTransport(
              TransportConfig.builder("http://upstream.invalid")
                  .proxy("http://user@" + proxy.url().substring("http://".length()))
                  .build())) {
        assertThat(t.send(TransportRequest.get("/x").build()).status()).isEqualTo(200);
      }
    }
    // default ports only build the selector; no request is sent
    new HttpTransport(TransportConfig.builder("http://h").proxy("http://proxy.invalid").build())
        .close();
    new HttpTransport(TransportConfig.builder("http://h").proxy("https://proxy.invalid").build())
        .close();
  }

  @Test
  void asSdkExceptionMapsThrowables() {
    assertThat(HttpTransport.asSdkException(new CancellationException(), "op"))
        .isInstanceOf(CancelledException.class);
    assertThat(HttpTransport.asSdkException(new InterruptedException(), "op"))
        .isInstanceOf(CancelledException.class);
    assertThat(
            HttpTransport.asSdkException(
                new java.util.concurrent.CompletionException(new IllegalStateException("x")), "op"))
        .isInstanceOf(UnavailableException.class)
        .hasMessageContaining("IllegalStateException");
    NotFoundException nf = new NotFoundException("nf");
    assertThat(HttpTransport.asSdkException(new java.util.concurrent.ExecutionException(nf), "op"))
        .isSameAs(nf);
  }

  @Test
  void errorMessageVariants() {
    Map<String, List<String>> json = Map.of("Content-Type", List.of("application/json"));
    Map<String, List<String>> text = Map.of("content-type", List.of("text/plain"));
    Map<String, List<String>> html = Map.of("Content-Type", List.of("text/html"));
    assertThat(HttpTransport.errorMessage("op", 404, json, null, List.of()))
        .isEqualTo("op: not found (HTTP 404)");
    assertThat(
            HttpTransport.errorMessage(
                "op", 400, json, b("{\"error\":{\"message\":\"bad\"}}"), List.of()))
        .isEqualTo("op: bad request: bad (HTTP 400)");
    assertThat(HttpTransport.errorMessage("op", 400, json, b("[\"a\", 1, \"b\"]"), List.of()))
        .isEqualTo("op: bad request: a; b (HTTP 400)");
    assertThat(HttpTransport.errorMessage("op", 400, json, b("[1]"), List.of()))
        .isEqualTo("op: bad request (HTTP 400)");
    assertThat(
            HttpTransport.errorMessage(
                "op", 400, json, b("{\"error\":null,\"detail\":\"d\"}"), List.of()))
        .isEqualTo("op: bad request: d (HTTP 400)");
    assertThat(HttpTransport.errorMessage("op", 400, json, b("{\"other\":1}"), List.of()))
        .isEqualTo("op: bad request (HTTP 400)");
    assertThat(HttpTransport.errorMessage("op", 400, json, b("{broken"), List.of()))
        .isEqualTo("op: bad request (HTTP 400)");
    assertThat(HttpTransport.errorMessage("op", 400, json, b("\"Bad Request\""), List.of()))
        .isEqualTo("op: bad request (HTTP 400)");
    assertThat(HttpTransport.errorMessage("op", 418, text, b("  I'm a\n teapot "), List.of()))
        .isEqualTo("op: client error: I'm a teapot (HTTP 418)");
    assertThat(HttpTransport.errorMessage("op", 500, html, b("<html>secret</html>"), List.of()))
        .isEqualTo("op: internal server error (HTTP 500)");
    assertThat(
            HttpTransport.errorMessage("op", 401, text, b("token Abcdefgh123 rejected"), List.of()))
        .isEqualTo("op: unauthorized: token [REDACTED] rejected (HTTP 401)");
    String longText = "x".repeat(400);
    assertThat(HttpTransport.errorMessage("op", 400, text, b(longText), List.of()))
        .hasSize("op: bad request: ".length() + 300 + 1 + " (HTTP 400)".length());
    assertThat(
            HttpTransport.errorMessage(
                "op", 400, Map.of("X", List.of()), b("{\"msg\":\"m\"}"), List.of()))
        .isEqualTo("op: bad request: m (HTTP 400)");
  }

  private static byte[] b(String s) {
    return s.getBytes(java.nio.charset.StandardCharsets.UTF_8);
  }

