  @Test
  void queryParametersKeepInsertionOrder() {
    server.enqueue(200, "{}");
    try (HttpTransport t = transport(config())) {
      TransportRequest req =
          TransportRequest.get("/q")
              .query("z", 1)
              .query("a", 2)
              .query("m", 3)
              .query("z", 4)
              .header("B", "1")
              .header("A", "2")
              .build();
      assertThat(req.query().keySet()).containsExactly("z", "a", "m");
      assertThat(req.headers().keySet()).containsExactly("B", "A");
      t.send(req);
      assertThat(server.requests().get(0).uri()).isEqualTo("/q?z=1&z=4&a=2&m=3");
    }
    assertThatThrownBy(() -> TransportRequest.get("/x").header("A", null).build())
        .isInstanceOf(NullPointerException.class);
  }

