  @Test
  void acceptedStatusBodyIsDecoded() {
    server.enqueue(404, "{\"data\":null,\"metadata\":{\"deleted\":true}}");
    server.enqueue(429, "plain", "Content-Type", "text/plain");
    try (HttpTransport t = transport(config())) {
      TransportResponse r = t.send(TransportRequest.get("/kv").acceptStatus(404).build());
      assertThat(r.status()).isEqualTo(404);
      assertThat(r.jsonNode().get("metadata").get("deleted").asBoolean()).isTrue();
      TransportResponse h = t.send(TransportRequest.get("/health").acceptAnyStatus().build());
      assertThat(h.status()).isEqualTo(429);
      assertThat(h.text()).isEqualTo("plain");
      assertThat(server.requests()).hasSize(2);
    }
  }

  @Test
  void vendorRateLimitHeaderIsRetryHint() {
    server
        .enqueue(429, "{}", "X-RateLimit-Reset", "0.2")
        .enqueue(200, "{}")
        .enqueue(429, "{}", "X-RateLimit-Reset", "120");
    try (HttpTransport t =
        transport(config().retryAfterHeaders("x-ratelimit-reset", "X-Other-Reset"))) {
      long start = System.nanoTime();
      TransportResponse r = t.send(TransportRequest.get("/x").build());
      assertThat(r.attempts()).isEqualTo(2);
      assertThat(TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start))
          .isGreaterThanOrEqualTo(200);
      assertThatThrownBy(() -> t.send(TransportRequest.get("/x").build()))
          .isInstanceOfSatisfying(
              RateLimitException.class,
              e -> assertThat(e.retryAfter()).contains(Duration.ofSeconds(120)));
      assertThat(t.config().retryAfterHeaders())
          .containsExactly("x-ratelimit-reset", "X-Other-Reset");
    }
    assertThatThrownBy(() -> TransportConfig.builder("http://h").retryAfterHeaders((String) null))
        .isInstanceOf(NullPointerException.class);
  }

  @Test
  void parseRateLimitResetVariants() {
    Instant now = Instant.parse("2026-01-01T00:00:00Z");
    assertThat(RetryPolicy.parseRateLimitReset("2", now)).contains(Duration.ofSeconds(2));
    assertThat(RetryPolicy.parseRateLimitReset("1.5", now)).contains(Duration.ofMillis(1500));
    long epoch = now.getEpochSecond();
    assertThat(RetryPolicy.parseRateLimitReset(Long.toString(epoch + 30), now))
        .contains(Duration.ofSeconds(30));
    assertThat(RetryPolicy.parseRateLimitReset(Long.toString(epoch - 30), now))
        .contains(Duration.ZERO);
    String date =
        DateTimeFormatter.RFC_1123_DATE_TIME.format(
            ZonedDateTime.ofInstant(now.plusSeconds(5), ZoneOffset.UTC));
    assertThat(RetryPolicy.parseRateLimitReset(date, now)).contains(Duration.ofSeconds(5));
    assertThat(RetryPolicy.parseRateLimitReset("soon", now)).isEmpty();
    assertThat(RetryPolicy.parseRateLimitReset(null, now)).isEmpty();
  }

  @Test
  void errorMapperReplacesErrorBeforeHooksAndRetries() {
    List<ZipkinException> seen = new CopyOnWriteArrayList<>();
    Hooks hooks =
        new Hooks() {
          @Override
          public void onError(ErrorInfo info) {
            seen.add(info.error());
          }
        };
    ErrorMapper mapper =
        (resp, err) -> {
          if (resp.status() == 403) {
            return new AuthenticationException(
                err.getMessage(), resp.status(), err.requestId().orElse(null), null, null);
          }
          if (resp.status() == 503 && resp.text().contains("forever")) {
            return ZipkinException.of(
                ErrorCode.UNAVAILABLE, "op: down for good", 503, null, false, null, null);
          }
          if (resp.status() == 502) {
            throw new IllegalStateException("mapper bug");
          }
          return resp.status() == 400 ? null : err;
        };
    server
        .enqueue(403, "{}")
        .enqueue(503, "{\"message\":\"forever\"}")
        .enqueue(502, "{}")
        .enqueue(200, "{}")
        .enqueue(400, "{}");
    try (HttpTransport t = transport(config().hooks(hooks).errorMapper(mapper))) {
      assertThatThrownBy(() -> t.send(TransportRequest.get("/a").build()))
          .isInstanceOf(AuthenticationException.class);
      assertThat(seen.get(0)).isInstanceOf(AuthenticationException.class);
      assertThatThrownBy(() -> t.send(TransportRequest.get("/b").build()))
          .isInstanceOfSatisfying(
              UnavailableException.class, e -> assertThat(e.retryable()).isFalse());
      // a failing mapper keeps the default error (and its retry)
      assertThat(t.send(TransportRequest.get("/c").build()).attempts()).isEqualTo(2);
      assertThatThrownBy(() -> t.send(TransportRequest.get("/d").build()))
          .isInstanceOf(ValidationException.class);
      assertThat(server.requests()).hasSize(5);
    }
    assertThat(TransportConfig.builder("http://h").errorMapper(null).build().errorMapper())
        .isSameAs(ErrorMapper.NONE);
    ZipkinException e = new NotFoundException("x");
    assertThat(ErrorMapper.NONE.map(null, e)).isSameAs(e);
  }

  @Test
  void explicitRetryableFlag() {
    for (ErrorCode code : ErrorCode.values()) {
      boolean flip = !code.retryable();
      var flipped = ZipkinException.of(code, "m", 409, "r", flip, null, null);
      assertThat(flipped.code()).isEqualTo(code);
      assertThat(flipped.retryable()).isEqualTo(!code.retryable());
      assertThat(flipped.httpStatus()).hasValue(409);
      assertThat(flipped.requestId()).contains("r");
    }
    class Aborted extends ConflictException {
      private static final long serialVersionUID = 1L;

      Aborted() {
        super("op: aborted", 409, null, true, Duration.ofSeconds(1), null);
      }
    }
    Aborted a = new Aborted();
    assertThat(a.code()).isEqualTo(ErrorCode.CONFLICT);
    assertThat(a.retryable()).isTrue();
    assertThat(a.retryAfter()).contains(Duration.ofSeconds(1));
  }

  @Test
  void mockServerKeepsRawBytes() throws Exception {
    byte[] gz;
    try (var bos = new java.io.ByteArrayOutputStream();
        var gzip = new java.util.zip.GZIPOutputStream(bos)) {
      gzip.write(b("hello"));
      gzip.finish();
      gz = bos.toByteArray();
    }
    byte[] payload = gz;
    server.enqueue(ex -> MockServer.sendBytes(ex, 200, payload));
    try (HttpTransport t = transport(config())) {
      TransportResponse r =
          t.send(TransportRequest.post("/gz").body(payload, "application/octet-stream").build());
      assertThat(r.body()).isEqualTo(payload);
    }
    MockServer.Recorded rec = server.requests().get(0);
    assertThat(rec.bytes()).isEqualTo(payload);
    assertThat(new MockServer.Recorded("GET", "/", Map.of(), "x", 0L).bytes()).isEqualTo(b("x"));
    assertThat(new MockServer.Recorded("GET", "/", Map.of(), null, 0L).bytes()).isEmpty();
  }
